export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const tMax = 2 * tTop;
  const t = Math.max(0, Math.min(time, tMax));

  const y = u * t - 0.5 * g * t * t;
  const v = u - g * t;
  const a = -g;
  const Fg = m * g;

  let state = "Ready to toss";
  if (t > 0 && t < tTop - 0.05) state = "Rising";
  else if (t >= tTop - 0.05 && t <= tTop + 0.05) state = "At the top";
  else if (t > tTop + 0.05 && t < tMax - 0.02) state = "Falling";
  else if (t >= tMax - 0.02) state = "Back at launch height";

  const scale = 120;
  const baseY = 320;
  const ballY = baseY - y * scale;
  const ballX = 160;

  const objects = [];

  objects.push(...sdk.panel({ x: 20, y: 40, w: 280, h: 360, title: "Motion", state }));
  objects.push(sdk.axis("axis.y", { x: 80, y: 320, length: 260, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));
  objects.push(sdk.circle("ball.toss", ballX, ballY, 24, { role: "output" }));

  objects.push(...sdk.vector("vec.v", { x: ballX + 20, y: ballY }, { value: v, direction: "up" }, { scale: 12, label: "v" }));
  objects.push(...sdk.vector(
    "vec.a",
    { x: ballX - 20,
    y: ballY },
    { value: a, direction: "up" },
    { scale: 12,
    label: "a" }
  ));

  objects.push(...sdk.callout(ballX + 50,
    ballY - 30,
    [
      `v: ${v.toFixed(2)} m/s`,
      `a: ${a.toFixed(2)} m/s^2`,
      `Fg: ${Fg.toFixed(1)} N`
    ],
    { id: "callout.toss" }
  ));

  objects.push(...sdk.panel({ x: 320, y: 40, w: 300, h: 360, title: "Velocity over Time", state: `t = ${t.toFixed(2)} s` }));

  const points = [];
  const steps = 20;
  for (let i = 0; i <= steps; i++) {
    const st = (i / steps) * tMax;
    const sv = u - g * st;
    points.push([st, sv]);
  }

  objects.push(
    sdk.plot("plot.vt", {
      x: 340,
      y: 90,
      w: 260,
      h: 240,
      axes: {
        x: { label: "Time", min: 0, max: Math.max(1.8, tMax), unit: "s" },
        y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
      },
      series: [
        { label: "v(t)", kind: "line", points: points }
      ]
    })
  );

  objects.push(
    sdk.text("plot.vt.note", 470, 360, "Slope a = -g", { align: "middle" }
  ));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: v },
        { id: "acceleration", value: a },
        { id: "force", value: Fg },
        { id: "motionState", value: state }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    }
  };
}
